add_filter( 'woocommerce_product_tabs', 'perfectpixel_rename_product_tabs', 98 );

function perfectpixel_rename_product_tabs( $tabs ) {
	global $product;
	$titles = array(
		'description'            => '{{tab_title_description}}',
		'additional_information' => '{{tab_title_additional}}',
		'reviews'                => '{{tab_title_reviews}}',
	);
	foreach ( $titles as $key => $title ) {
		if ( isset( $tabs[ $key ] ) && '' !== trim( $title ) ) {
			$count               = $product ? $product->get_review_count() : 0;
			$tabs[ $key ]['title'] = str_replace( '{count}', (int) $count, $title );
		}
	}
	return $tabs;
}
